const ledger = new DeliveryLedger(6);
const event = { sequence: 1, topic: 'created', payload: {} };
ledger.enqueue(event, ['audit']);

// failure at now=0 -> attempt 1 -> due should be 0 + 100ms = 100
ledger.failure(1, 'audit', 0, 'network');
console.log('ready at 50ms (expect 0):', ledger.ready(50).length);
console.log('ready at 100ms (expect 1):', ledger.ready(100).length);
console.log('pending:', ledger.pending().length);

// failure at now=1000 -> attempt 1 -> due = 1100
const l2 = new DeliveryLedger(6);
l2.enqueue(event, ['audit']);
l2.failure(1, 'audit', 1000, 'network');
console.log('ready at 1050 (expect 0):', l2.ready(1050).length);
console.log('ready at 1100 (expect 1):', l2.ready(1100).length);

// dead letter path
const l3 = new DeliveryLedger(2);
l3.enqueue(event, ['audit']);
l3.failure(1, 'audit', 0, 'e1');
l3.failure(1, 'audit', 0, 'e2');
console.log('dead letters:', l3.deadLetters().length);
" 2>&1

